import json,os,re
root='.'
for wf in ['wf_aabc0cb2-d31','wf_9777a563-c5e']:
    for f in sorted(os.listdir(wf)):
        if not (f.startswith('agent-') and f.endswith('.jsonl')): continue
        lab=json.load(open(os.path.join(wf,f.replace('.jsonl','.meta.json'))))['description']
        specs={}
        for l in open(os.path.join(wf,f)):
            r=json.loads(l)
            if r.get('type')!='assistant': continue
            for b in r['message'].get('content',[]):
                if b.get('type')!='tool_use': continue
                blob=b.get('input',{}).get('command','') if b['name']=='Bash' else json.dumps(b.get('input',{}))
                if 'Specification' not in blob: continue
                # find sed -n 'A,Bp' ... file  and any Specification path
                for m in re.finditer(r"Specification(?:-1\.0-frozen)?/([A-Za-z0-9_./-]+\.tex)", blob):
                    specs.setdefault(m.group(1), set())
                # attach any numeric ranges present in the same command
                rng=set(re.findall(r"(\d+),(\d+)p", blob)) | set(('%s'%x,'%s'%x) for x in re.findall(r"-n\s+'?(\d+)p", blob))
                for k in list(specs):
                    if k in blob:
                        specs[k] |= rng
        if specs:
            print('\n### %s / %s'%(wf[:13], lab))
            for k in sorted(specs):
                rr=sorted(specs[k], key=lambda t:int(t[0]))
                print('   %-50s %s'%(k, ' '.join('%s-%s'%t for t in rr)))
PY

