import json,os,re
from collections import defaultdict
auth=defaultdict(set)
for f in sorted(os.listdir('.')):
    if not (f.startswith('agent-') and f.endswith('.jsonl')): continue
    lab=json.load(open(f.replace('.jsonl','.meta.json')))['description']
    for l in open(f):
        r=json.loads(l)
        if r.get('type')!='assistant': continue
        for b in r['message'].get('content',[]):
            if b.get('type')!='tool_use': continue
            s=b.get('input',{}).get('command','') if b['name']=='Bash' else json.dumps(b.get('input',{}))
            for m in re.finditer(r'cat\s*>\s*\$?[A-Za-z0-9_/.${}-]*?((?:SK|SQ)\d+[A-Za-z0-9]*)\.fss', s):
                auth[lab].add(m.group(1))
            for m in re.finditer(r'component\s+((?:SK|SQ)\d+[A-Za-z0-9]*)', s):
                auth[lab].add(m.group(1))
for k in sorted(auth):
    print('%-13s %2d  %s'%(k,len(auth[k]),' '.join(sorted(auth[k]))))
